SELECT DISTINCT p.id, p.permission_name, p.permission_desc, p.resource_type, p.resource_key, p.parent_id, p.status, p.created_at, p.updated_at, p.deleted FROM sys_permission p INNER JOIN sys_role_permission rp ON p.id = rp.permission_id INNER JOIN sys_role r ON rp.role_id = r.id WHERE rp.role_id IN
#{id}
AND r.status = 1 AND r.deleted = 0 AND p.status = 1 AND p.deleted = 0
